// Contract and client of the Supplements view (docs/design.md, "Suplementacja"). Conventions as in ./types.ts:
// - dates: ISO `YYYY-MM-DD` (local, Europe/Warsaw); timestamps: ISO 8601 with offset; reminder times "HH:MM" local
// - the checklist is generated by the backend from supplement_rule + the plan; regularity and stock forecast
//   are projections of supplement_log / supplement_stock; the UI only formats and counts ticks
// - supplement_log is append-only: logSupplement() appends SupplementTaken / SupplementSkipped, the latest event
//   of the day wins (unticking a taken item appends SupplementSkipped)
// - whey protein is logged in Fitatu as a meal; here it is only a tick (no macros, `countedInFitatu`)
// - the coach may only propose a reminder time; it never adds supplements or changes doses
import type { DayType } from './nutrition'
import type { Tone } from './types'
import { mockMode } from './client'
import {
  supplementsFull,
  supplementsLogMock,
  supplementsProposalDecideMock,
  supplementsStage1,
} from './mocks/supplements'

/** Time of day from supplement_rule. */
export type SupplementSlot = 'morning' | 'before' | 'during' | 'after' | 'evening'

/** When a rule applies (supplement_rule.when); also the basis of regularity and stock forecast. */
export type SupplementWhen = 'daily' | 'run_day' | 'long_run' | 'quality_run' | 'strength_day' | 'training_day'

export type DoseUnit = 'IU' | 'mg' | 'g' | 'capsule' | 'tablet' | 'sachet'

export type SupplementStatus = 'pending' | 'taken' | 'skipped'

export type SupplementLogStatus = Exclude<SupplementStatus, 'pending'>

// ---------- GET /api/supplements ----------

export interface SupplementsResponse {
  date: string
  /** Today's day type from the plan / activities; null when unknown. */
  dayType: DayType | null
  /** Today's checklist in slot order (morning → evening). Empty when no supplements are set up. */
  checklist: SupplementItem[]
  /** Last 30 complete days (today excluded). */
  regularity: { from: string; to: string; items: SupplementRegularity[] }
  /** Sorted by urgency (fewest days left first). */
  stock: SupplementStock[]
  /** Pending coach proposal of a reminder time (stage 3); null when none. */
  proposal: ReminderProposal | null
}

export interface SupplementItem {
  /** supplement.id, used by logSupplement(). */
  id: string
  name: string
  dose: { amount: number; unit: DoseUnit }
  /** User-entered note from the rule, e.g. "z posiłkiem", "60 min przed", "bieg > 90 min". */
  note: string | null
  /** Logged as a meal in Fitatu; the UI shows that instead of `note`. */
  countedInFitatu: boolean
  slot: SupplementSlot
  /** Reminder time "HH:MM" for morning/evening items; null = tied to the session (before/during/after). */
  remindAt: string | null
  status: SupplementStatus
  /** Time of the latest log event today. */
  loggedAt: string | null
}

export type RegularityDay = 'taken' | 'missed' | 'na'

export interface SupplementRegularity {
  supplementId: string
  name: string
  when: SupplementWhen
  /** One entry per day of `regularity.from..to`, oldest first; na = rule did not apply that day. */
  days: RegularityDay[]
  taken: number
  /** Days the rule applied. */
  applicable: number
  /** taken / applicable in %, rounded. */
  pct: number
  /** warn = regularity below the backend threshold. */
  tone: Tone
}

export interface SupplementStock {
  supplementId: string
  name: string
  left: { amount: number; unit: DoseUnit }
  /** Forecast: how many `per` units the stock lasts (days for daily rules, long runs for long_run, ...). */
  lasts: { count: number; per: SupplementWhen }
  /** true when the stock is below 14 days: shown as "zamów". */
  reorder: boolean
}

export interface ReminderProposal {
  /** plan_event proposal id (PlanChangeProposed). */
  id: string
  supplementId: string
  supplementName: string
  /** Coach prose (LLM). */
  text: string
  currentTime: string
  proposedTime: string
}

// ---------- client ----------

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const resp = await fetch(path, {
    ...init,
    headers: { accept: 'application/json', ...(init?.body ? { 'content-type': 'application/json' } : {}) },
  })
  if (!resp.ok) throw new Error(`${path}: HTTP ${resp.status}`)
  return resp.status === 204 ? (undefined as T) : ((await resp.json()) as T)
}

const delay = <T>(value: T) => new Promise<T>((resolve) => setTimeout(() => resolve(structuredClone(value)), 150))

export function getSupplements(): Promise<SupplementsResponse> {
  switch (mockMode()) {
    case 'full':
      return delay(supplementsFull())
    case 'stage1':
      return delay(supplementsStage1)
    default:
      return request('/api/supplements')
  }
}

/**
 * POST /api/supplements/{id}/log  body { status: 'taken' | 'skipped', date }
 * Appends SupplementTaken / SupplementSkipped for today; returns the updated item.
 */
export async function logSupplement(id: string, status: SupplementLogStatus, date: string): Promise<SupplementItem> {
  if (mockMode() !== 'off') return delay(supplementsLogMock(id, status))
  return request(`/api/supplements/${encodeURIComponent(id)}/log`, {
    method: 'POST',
    body: JSON.stringify({ status, date }),
  })
}

/**
 * POST /api/proposals/{id}/accept | /reject  body { comment: null }: the same decision endpoints as the
 * Proposals view (src/api/proposals.ts). Accepting appends PlanChangeAccepted; the backend moves the reminder.
 * The response (ProposalDecision) is not needed here; the view reloads.
 */
export async function decideReminderProposal(id: string, decision: 'accept' | 'reject'): Promise<void> {
  if (mockMode() !== 'off') return delay(supplementsProposalDecideMock(id, decision))
  await request<unknown>(`/api/proposals/${encodeURIComponent(id)}/${decision}`, {
    method: 'POST',
    body: JSON.stringify({ comment: null }),
  })
}
